export interface Invoice {
  id: string;
  status: 'paid' | 'open' | string;
  dueDate: Date;
}

interface Mailer {
  send(invoice: Invoice): Promise<void>;
}

const OVERDUE_THRESHOLD_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

function daysPastDue(invoice: Invoice, now: Date = new Date()): number {
  return (now.getTime() - invoice.dueDate.getTime()) / MS_PER_DAY;
}

export async function notifyOverdue(invoices: Invoice[], mailer: Mailer): Promise<void> {
  const targets = invoices.filter(
    (inv) => inv.status !== 'paid' && daysPastDue(inv) > OVERDUE_THRESHOLD_DAYS
  );

  for (const invoice of targets) {
    try {
      await mailer.send(invoice);
    } catch {
      // A failing mailer must not throw out of notifyOverdue (test 2) and
      // must not stop the rest of the batch — one bad SMTP attempt shouldn't
      // silently drop notifications for the other overdue invoices.
    }
  }
}
```

